       "30,6",
       "30,7 Аэробты және анаэробты тыныс алу Тыныс алу – бұл организмдердің өмір сүру үшін қажетті энергия алу процесі. Адамдар мен жануарлар да, өсімдіктер де тыныс алады. Бірақ тыныс алу екі түрлі жолмен жүреді: аэробты және анаэробты. Олардың екеуі де энергия алуға көмектеседі, бірақ айырмашылықтары бар. Аэробты тыныс алу дегеніміз – оттегімен тыныс алу. Бұл процесс өте тиімді, себебі ол көп энергия береді. Адамдар мен жануарлар көбінесе аэробты тыныс алу арқылы энергия алады. Мұнда глюкоза оттегімен реакцияға түсіп, көмірқышқыл газын және суды шығарады. Бұл процесстен көп АТФ (энергия молекулалары) өндіріледі. Сондықтан бұл жолмен энергия алу ұзақ уақытқа жетеді.Ал анаэробты тыныс алу дегеніміз – оттексіз тыныс алу. Бұл процесс көбінесе оттегі жетіспейтін жағдайда іске асады. Мысалы, біз жүгіргенде немесе физикалық күш жұмсаған кезде, организміміз тез энергия алуға мұқтаж болады. Бірақ анаэробты тыныс алу көп энергия бермейді. Оның орнына, лактат немесе этанол сияқты өнімдер пайда болады, ол организм үшін пайдалы емес."
